public class Program {
  static int find(int[] a,int l,int r,int x,int[] probes){
    if(l>r)return -1;
    probes[0]++; int m=(l+r)>>>1;
    return a[m]==x?m:(a[m]<x?find(a,m+1,r,x,probes):find(a,l,m-1,x,probes));
  }
  public static void main(String[] args){
    int[] p={0}; int[] a={1,3,5,7,9,11,13,15,17};
    System.out.println(find(a,0,a.length-1,8,p)+":"+p[0]);
  }
}

