    var r=java.util.stream.Stream.of("ant","ape","bee","bat").collect(java.util.stream.Collectors.groupingBy(s->s.charAt(0),java.util.TreeMap::new,java.util.stream.Collectors.mapping(String::length,java.util.stream.Collectors.summingInt(Integer::intValue))));System.out.println(r);
  }
