public class Program {
  static class Ledger{
    final java.util.Map<String,Integer> m=new java.util.LinkedHashMap<>();
    void add(String k,int d){int n=m.getOrDefault(k,0)+d;if(n==0)m.remove(k);else m.put(k,n);}
    int checksum(){return m.values().stream().mapToInt(Integer::intValue).sum()+m.size();}
  }
  public static void main(String[] args){
    Ledger x=new Ledger();
    x.add("A",3);x.add("B",2);x.add("A",-1);x.add("C",4);x.add("B",-2);x.add("A",2);
    System.out.println(x.m+":"+x.checksum());
  }
}
